package com.menter.treatmentvault.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.menter.treatmentvault.*;import com.menter.treatmentvault.data.*;import kotlinx.coroutines.launch
@Composable fun ExpenseScreen(back:()->Unit){val dao=(androidx.compose.ui.platform.LocalContext.current.applicationContext as TreatmentVaultApplication).database.dao();val list by dao.expenses().collectAsState(emptyList());val scope=rememberCoroutineScope();var add by remember{mutableStateOf(false)};Page("费用记录",back){Text("合计 ¥${"%.2f".format(list.sumOf{it.amount})}",style=MaterialTheme.typography.headlineSmall);LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(list){v->Card{Row(Modifier.padding(12.dp).fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(v.type);Text("${v.date} ${v.merchant}")};Text("¥${"%.2f".format(v.amount)}")}}}};Button({add=true},Modifier.fillMaxWidth()){Text("新增费用")}}
if(add){var date by remember{mutableStateOf("")};var type by remember{mutableStateOf("其他")};var amount by remember{mutableStateOf("")};AlertDialog({add=false},{TextButton({amount.toDoubleOrNull()?.let{a->scope.launch{dao.saveExpense(ExpenseEntity(date=date,type=type,amount=a,selfPayAmount=a));add=false}}}){Text("保存")}},dismissButton={TextButton({add=false}){Text("取消")}},title={Text("新增费用")},text={Column{Field(date,{date=it},"日期");Field(type,{type=it},"类型");Field(amount,{amount=it},"金额")}})} }
